    pieces: Array.from(
      { length: count },
      (): Pose => ({ position: [0, 0, 0], rotation: [0, 0, 0], size: [1, 1] }),
    ),
    turn: [0, 0],
    anchor: [0, 0],
    drift: 0,
    span: 0,
    rise: 0,
    near: 0,
    sway: [0, 0, 0],
    floor: 0,
    over: 0,
  };
