  notes: [\"Seven probe connectors form an explanatory measurement loom, derived from fixture access and bench observation. Not actual cabling or wiring.\", \"Connectors open into ordered command, observation and question positions. Spacing is not elapsed time, and no waveform is drawn.\", \"The loom rejoins while Estimate and Run retain separate labels: connecting evidence does not erase its limits.\"],
 },
};
function Fixture({material,look,index}: PieceProps) {
 return <group>
  <mesh castShadow receiveShadow><boxGeometry args={[1,.88,.64]}/><meshStandardMaterial color={look.surface.color} roughness={.6} metalness={.3}/></mesh>
  {[-.37,.37].map(x=><mesh key={x} position={[x,0,.38]}><boxGeometry args={[.12,.9,.16]}/><meshStandardMaterial color={look.accent} roughness={.45} metalness={.5}/></mesh>)}
  <mesh position={[0,.32,.62]} rotation={[Math.PI/2,0,0]}><cylinderGeometry args={[.055,.075,.48,12]}/><meshStandardMaterial color=\"#a9b6b9\" metalness={.85} roughness={.3}/></mesh>
  <mesh position={[0,-.12,.33]} material={material}><planeGeometry args={[.65,.4]}/></mesh>
  <mesh position={[0,-.36,.4]}><sphereGeometry args={[.035,10,8]}/><meshStandardMaterial color={index<5?look.accent:look.ink}/></mesh>
 </group>;
}
function Sensor({material,look,index}: PieceProps) {
 return <group>
